```python
class ListNode:
    def __init__(self, x):
        self.val = x
        self.next = None

def sort_linked_list(head):
    if head is None or head.next is None:
        return head

    mid = find_middle(head)
    left = sort_linked_list(head)
    right = sort_linked_list(mid.next)

    return merge_sorted(left, right)

def find_middle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
    return slow

def merge_sorted(left, right):
    result = ListNode(0)
    current = result

    while left is not None and right is not None:
        if left.val <= right.val:
            current.next = left
            left = left.next
        else:
            current.next = right
            right = right.next
        current = current.next

    if left is not None:
        current.next = left
    else:
        current.next = right

    return result.next
```

This function first finds the middle of the linked list, then recursively sorts the two halves of the list. Finally, it merges the two sorted halves into one sorted linked list.

Please note that this solution assumes that the input linked list is not empty. If it could be empty, you would need to add a check for `head is None` at the beginning of the function.
